    const nonLocalTp = num(sc.nonLocalTp, 2 + ((h >> 2) % 3));
    const localSpeed = num(sc.localSpeed, 22 + (h % 8));
    const nonLocalSpeed = num(sc.nonLocalSpeed, 32 + ((h >> 5) % 10));
    const openHour = 5 + (h % 3);
    const closeHour = 21 + ((h >> 4) % 3);
